mapper.select:
/* com.kt.openapi.web.bbs.cmn.dao.BbsCmnDAO.selNoticeList */ (SELECT 0 AS rownum ,Row_number() OVER( ORDER BY A.PSTING_ID DESC) AS ROW ,A.PSTING_ID ,TITLE ,SBST ,PSTING_NO ,BBS_TYPE_CD ,IMPT_YN ,SHOW_YN ,TO_CHAR(REG_DT, 'YYYY-MM-DD') AS REG_DT ,COALESCE(REGR,'') AS REGR ,AMD_DT ,COALESCE(AMDR,'') AS AMDR ,COALESCE(B.CNT,0) AS CNT FROM KOA_TB_BBS A LEFT OUTER JOIN ( SELECT COUNT(1) AS CNT, A.PSTING_ID FROM KOA_TB_BBS_ATC A GROUP BY A.PSTING_ID ) B ON (B.PSTING_ID = A.PSTING_ID) WHERE 1=1 AND IMPT_YN = 'Y' AND SHOW_YN = 'Y' AND DEL_YN = 'N'
AND BBS_TYPE_CD = #{bbsTypeCd}
LIMIT 5)
UNION ALL
SELECT Row_number() OVER( ORDER BY A.PSTING_ID DESC) rownum , 0 AS ROW , A.PSTING_ID ,TITLE ,SBST ,PSTING_NO ,BBS_TYPE_CD ,IMPT_YN ,SHOW_YN ,TO_CHAR(REG_DT, 'YYYY-MM-DD') AS REG_DT ,COALESCE(REGR,'') AS REGR ,AMD_DT ,COALESCE(AMDR,'') AS AMDR ,COALESCE(B.CNT,0) AS CNT FROM KOA_TB_BBS A LEFT OUTER JOIN ( SELECT COUNT(1) AS CNT, A.PSTING_ID FROM KOA_TB_BBS_ATC A GROUP BY A.PSTING_ID ) B ON (B.PSTING_ID = A.PSTING_ID) WHERE 1=1
AND UPPER(TITLE) LIKE '%' + UPPER(#{searchKeyword}) + '%'
AND UPPER(SBST) LIKE '%' + UPPER(#{searchKeyword}) + '%'
AND (UPPER(TITLE) LIKE '%' + UPPER(#{searchKeyword}) + '%' OR UPPER(SBST) LIKE '%' + UPPER(#{searchKeyword}) + '%')
AND BBS_TYPE_CD = #{bbsTypeCd}
AND IMPT_YN = 'N' AND SHOW_YN = 'Y' AND DEL_YN = 'N'

/* com.kt.openapi.web.bbs.cmn.dao.BbsCmnDAO.selNoticeListCnt */ SELECT COUNT(1) AS cnt FROM KOA_TB_BBS WHERE 1=1
AND UPPER(TITLE) LIKE '%' + UPPER(#{searchKeyword}) + '%'
AND UPPER(SBST) LIKE '%' + UPPER(#{searchKeyword}) + '%'
AND (UPPER(TITLE) LIKE '%' + UPPER(#{searchKeyword}) + '%' OR UPPER(SBST) LIKE '%' + UPPER(#{searchKeyword}) + '%')
AND SHOW_YN = 'Y' AND IMPT_YN = 'N' AND DEL_YN = 'N'
AND BBS_TYPE_CD = #{bbsTypeCd}

/* com.kt.openapi.web.bbs.cmn.dao.BbsCmnDAO.selNoticeView */ SELECT B.PSTING_ID ,B.TITLE ,B.SBST ,B.BBS_TYPE_CD ,B.IMPT_YN ,TO_CHAR(B.REG_DT, 'YYYY-MM-DD') AS REG_DT ,TO_CHAR(B.AMD_DT, 'YYYY-MM-DD') AS AMD_DT ,COALESCE(B.AMDR,'') AS AMDR ,COALESCE(B.REGR,'') AS REGR ,B.SHOW_YN ,B.PREV_PSTING_ID ,B.NEXT_PSTING_ID ,B.PREV_TITLE ,B.NEXT_TITLE FROM ( SELECT A.* , LAG(A.PSTING_ID, 1, 0) OVER ( ORDER BY A.PSTING_ID DESC) AS PREV_PSTING_ID , LEAD(A.PSTING_ID, 1, 0) OVER ( ORDER BY A.PSTING_ID DESC) AS NEXT_PSTING_ID , LAG(A.TITLE, 1, '') OVER ( ORDER BY A.PSTING_ID DESC) AS PREV_TITLE , LEAD(A.TITLE, 1, '') OVER ( ORDER BY A.PSTING_ID DESC) AS NEXT_TITLE FROM KOA_TB_BBS A WHERE 1=1 AND SHOW_YN = 'Y' AND DEL_YN = 'N'
AND IMPT_YN = #{imptYn}
AND BBS_TYPE_CD = #{bbsTypeCd}
) B WHERE 1=1
AND B.PSTING_ID = #{pstingId}

/* com.kt.openapi.web.bbs.cmn.dao.BbsCmnDAO.selForumList */ SELECT Row_number() OVER( ORDER BY A.PSTING_ID DESC) rownum ,A.PSTING_ID ,A.TITLE ,A.PSTING_NO ,A.SBST ,A.BBS_TYPE_CD ,A.IMPT_YN , TO_CHAR(A.REG_DT, 'YYYY-MM-DD') AS REG_DT ,COALESCE(A.REGR,'') AS REGR ,A.AMD_DT ,COALESCE(A.AMDR,'') AS AMDR ,A.SHOW_YN , COALESCE(B.CNT,0) AS REQ_CNT , TO_CHAR(A.RETV_NUM, 'FM999G999G999G999G990') as RETV_NUM FROM KOA_TB_BBS A LEFT OUTER JOIN ( SELECT COUNT(1) AS CNT , A.PSTING_ID FROM KOA_TB_BBS_REPL A WHERE A.DEL_YN='N' GROUP BY A.PSTING_ID ) B ON (B.PSTING_ID = A.PSTING_ID) WHERE 1=1
AND UPPER(TITLE) LIKE '%' + UPPER(#{searchKeyword}) + '%'
AND UPPER(SBST) LIKE '%' + UPPER(#{searchKeyword}) + '%'
AND (UPPER(TITLE) LIKE '%' + UPPER(#{searchKeyword}) + '%' OR UPPER(SBST) LIKE '%' + UPPER(#{searchKeyword}) + '%')
AND BBS_TYPE_CD = #{bbsTypeCd}
AND SHOW_YN = 'Y' AND DEL_YN = 'N'

/* com.kt.openapi.web.bbs.cmn.dao.BbsCmnDAO.selForumListCnt */ SELECT COUNT(1) AS cnt FROM KOA_TB_BBS WHERE 1=1
AND UPPER(TITLE) LIKE '%' + UPPER(#{searchKeyword}) + '%'
AND UPPER(SBST) LIKE '%' + UPPER(#{searchKeyword}) + '%'
AND (UPPER(TITLE) LIKE '%' + UPPER(#{searchKeyword}) + '%' OR UPPER(SBST) LIKE '%' + UPPER(#{searchKeyword}) + '%')
AND SHOW_YN = 'Y' AND DEL_YN = 'N'
AND BBS_TYPE_CD = #{bbsTypeCd}

/* com.kt.openapi.web.bbs.cmn.dao.BbsCmnDAO.selCommentList */ SELECT REPL_NO , PSTING_ID , SBST , TO_CHAR(REG_DT, 'YYYY-MM-DD') AS REG_DT , COALESCE(REGR,'') AS REGR , AMD_DT , COALESCE(AMDR,'') AS AMDR FROM KOA_TB_BBS_REPL WHERE 1=1 AND DEL_YN = 'N'
AND PSTING_ID = #{pstingId}
ORDER BY REG_DT DESC

mapper.update:

/* com.kt.openapi.web.bbs.cmn.dao.BbsCmnDAO.updForumComment */ 
UPDATE KOA_TB_BBS_REPL
   SET 
      SBST = #{sbst}
      ,AMD_DT =NOW()
      ,AMDR = #{regr}
 WHERE REPL_NO = #{replNo}
 	 AND PSTING_ID = #{pstingId}


/* com.kt.openapi.web.bbs.cmn.dao.BbsCmnDAO.delForumCommentAjax */ 
UPDATE KOA_TB_BBS_REPL
   SET 
      DEL_YN = 'Y'
      ,AMD_DT =NOW()
      ,AMDR = #{regr}
 WHERE REPL_NO = #{replNo}
 	 AND PSTING_ID = #{pstingId}

/* com.kt.openapi.web.bbs.cmn.dao.BbsCmnDAO.delForumAjax */ 
UPDATE KOA_TB_BBS
   SET 
      DEL_YN = 'Y'
      ,AMD_DT =NOW()
      ,AMDR = #{regr}
WHERE 1=1
 	 AND PSTING_ID = #{pstingId}

	AND BBS_TYPE_CD = #{bbsTypeCd}


/* com.kt.openapi.web.bbs.cmn.dao.BbsCmnDAO.updForum */ 
UPDATE KOA_TB_BBS
   SET 
      TITLE =#{title}
      ,SBST = #{sbst}
      ,AMD_DT = NOW()
      ,AMDR = #{regr}
 WHERE  PSTING_ID = #{pstingId}

	AND BBS_TYPE_CD = #{bbsTypeCd}


/* com.kt.openapi.web.bbs.cmn.dao.BbsCmnDAO.updReadCnt */ 
UPDATE KOA_TB_BBS
   SET 
      RETV_NUM = (SELECT RETV_NUM+1 FROM KOA_TB_BBS  WHERE  PSTING_ID = #{pstingId})
 WHERE  PSTING_ID = #{pstingId}
